const nutritionDefaults={mealCount:4,maxCookingMinutes:60,allowAhead:true,foodBudget:'everyday',allergens:[],excludedFoods:'',favoriteFoods:'',dairyPreference:'all',nutritionFocus:'balanced',nutritionHealth:'general'};
